+
+    button:hover {
+      background: linear-gradient(180deg, #3b82f6, #2563eb);
+    }
+
+    input[type="checkbox"]:focus-visible,
+    button:focus-visible,
+    a:focus-visible {
+      outline: 3px solid var(--color-focus);
+      outline-offset: 3px;
+    }
+
+    .form-field[data-invalid="true"] {
+      border-color: var(--color-danger);
