    body {
      margin: 0;
      min-height: 100vh;
      color: var(--color-text);
      background: transparent;
    }

    a {
      color: var(--color-link);
    }

    a:hover {
      color: #bfdbfe;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      transform: translateY(-220%);
      padding: 0.75rem 1rem;
      border-radius: 0.75rem;
      background: var(--color-text);
      color: #020617;
      font-weight: 700;
    }

    .skip-link:focus {
      transform: translateY(0);
      outline: 3px solid var(--color-focus);
      outline-offset: 2px;
    }

    main {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 2rem 1rem;
    }

    .card {
      width: min(100%, 30rem);
      padding: 2rem;
      border: 1px solid var(--color-border);
      border-radius: 1.25rem;
      background: linear-gradient(180deg, rgba(31, 41, 55, 0.96), rgba(15, 23, 42, 0.98));
      box-shadow: var(--shadow-panel);
    }

    h1 {
      margin: 0 0 0.75rem;
      font-size: clamp(1.8rem, 4vw, 2.35rem);
      line-height: 1.1;
    }

    .intro {
      margin: 0 0 1.5rem;
      color: var(--color-muted-text);
      line-height: 1.5;
    }

    form {
      display: grid;
      gap: 1.25rem;
    }

    .form-field {
      padding: 1rem;
      border: 1px solid var(--color-border);
      border-radius: 1rem;
      background: var(--color-panel);
    }

    .checkbox-row {
      display: flex;
      align-items: start;
      gap: 0.85rem;
    }

    input[type="checkbox"] {
      width: 1.2rem;
      height: 1.2rem;
      margin: 0.15rem 0 0;
      accent-color: #60a5fa;
    }

    label {
      font-weight: 600;
      line-height: 1.5;
    }

    .required-mark {
      color: #fcd34d;
      font-weight: 700;
    }

    .helper-text,
    .error-text,
    .status-text {
      margin: 0.75rem 0 0;
      line-height: 1.5;
    }

    .helper-text {
      color: var(--color-muted-text);
      font-size: 0.95rem;
    }

    .error-text {
      color: var(--color-danger);
      font-weight: 600;
    }

    .status-text {
      min-height: 1.5rem;
      color: var(--color-success);
      font-weight: 600;
    }

    button {
      justify-self: start;
      padding: 0.9rem 1.3rem;
      border: 1px solid var(--color-border-strong);
      border-radius: 999px;
      background: linear-gradient(180deg, #2563eb, #1d4ed8);
      color: var(--color-text);
      font: inherit;
      font-weight: 700;
      cursor: pointer;
    }

    button:hover {
      background: linear-gradient(180deg, #3b82f6, #2563eb);
    }

    input[type="checkbox"]:focus-visible,
    button:focus-visible,
    a:focus-visible {
      outline: 3px solid var(--color-focus);
      outline-offset: 3px;
    }

    .form-field[data-invalid="true"] {
      border-color: var(--color-danger);
    }

    [hidden] {
      display: none;
    }

    @media (max-width: 30rem) {
      .card {
        padding: 1.5rem;
      }
    }

    @media (forced-colors: active) {
      :root {
        --color-bg: Canvas;
        --color-panel: Canvas;
        --color-text: CanvasText;
        --color-muted-text: CanvasText;
        --color-link: LinkText;
        --color-border: ButtonBorder;
        --color-border-strong: ButtonBorder;
        --color-focus: Highlight;
        --color-danger: CanvasText;
        --color-success: CanvasText;
        --shadow-panel: none;
      }

      .card,
      .form-field,
      button {
        background: Canvas;
      }

      button {
        color: ButtonText;
      }

      input[type="checkbox"]:focus-visible,
      button:focus-visible,
      a:focus-visible,
      .skip-link:focus {
        outline-color: Highlight;
      }
    }
  </style>
</head>
<body>
  <script>
    const PageShell = ({ title, intro, children }) => `
      <a class="skip-link" href="#maincontent">Skip to main content</a>
      <main id="maincontent" tabindex="-1">
        <section class="card" aria-labelledby="page-title">
          <h1 id="page-title">${title}</h1>
          <p class="intro">${intro}</p>
          ${children}
        </section>
      </main>
    `;

    const ConsentField = () => `
      <div class="form-field" data-invalid="false">
        <div class="checkbox-row">
          <input
            id="consent"
            name="consent"
            type="checkbox"
            required
            aria-describedby="consent-help"
          >
          <label for="consent">
            I agree to the Terms of Use <span class="required-mark" aria-hidden="true">*</span>
          </label>
        </div>
        <p class="helper-text" id="consent-help">
          Required to continue. Please review the <a href="#" rel="noopener noreferrer">terms of use</a> before submitting.
        </p>
        <p class="error-text" id="consent-error" hidden>
          Error: You must agree to the Terms of Use before continuing.
        </p>
      </div>
    `;

    const ConsentForm = () => `
      <form id="consent-form" novalidate>
        ${ConsentField()}
        <button type="submit">Submit consent</button>
        <p class="status-text" id="form-status" aria-live="polite"></p>
      </form>
    `;

    const App = () =>
      PageShell({
        title: "Confirm your consent",
        intro: "Agree to the terms to finish this step.",
        children: ConsentForm()
      });

    document.body.insertAdjacentHTML("afterbegin", App());

    const form = document.getElementById("consent-form");
    const checkbox = document.getElementById("consent");
    const field = checkbox.closest(".form-field");
    const error = document.getElementById("consent-error");
    const status = document.getElementById("form-status");

    const showError = () => {
      field.dataset.invalid = "true";
      checkbox.setAttribute("aria-invalid", "true");
      checkbox.setAttribute("aria-describedby", "consent-help consent-error");
      error.hidden = false;
    };

    const clearError = () => {
      field.dataset.invalid = "false";
      checkbox.removeAttribute("aria-invalid");
      checkbox.setAttribute("aria-describedby", "consent-help");
      error.hidden = true;
    };

    checkbox.addEventListener("change", () => {
      status.textContent = "";
      if (checkbox.checked) {
        clearError();
      }
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      status.textContent = "";

      if (!checkbox.checked) {
        showError();
        checkbox.focus();
        return;
      }

      clearError();
      status.textContent = "Consent submitted.";
    });
  </script>
</body>
</html>
