  <script>
    const PageShell = ({ title, intro, children }) => `
      <a class="skip-link" href="#maincontent">Skip to main content</a>
      <main id="maincontent" tabindex="-1">
        <section class="card" aria-labelledby="page-title">
          <h1 id="page-title">${title}</h1>
          <p class="intro">${intro}</p>
          ${children}
        </section>
      </main>
    `;

    const ConsentField = () => `
      <div class="form-field" data-invalid="false">
        <div class="checkbox-row">
          <input
            id="consent"
            name="consent"
            type="checkbox"
            required
            aria-describedby="consent-help"
          >
          <label for="consent">
            I agree to the Terms of Use <span class="required-mark" aria-hidden="true">*</span>
          </label>
        </div>
        <p class="helper-text" id="consent-help">
          Required to continue. Please review the <a href="/terms-of-use">terms of use</a> before submitting.
        </p>
        <p class="error-text" id="consent-error" hidden>
          Error: You must agree to the Terms of Use before continuing.
        </p>
      </div>
    `;

    const ConsentForm = () => `
      <form id="consent-form" novalidate>
        ${ConsentField()}
        <button type="submit">Submit consent</button>
        <p class="status-text" id="form-status" aria-live="polite"></p>
      </form>
    `;

    const App = () =>
      PageShell({
        title: "Confirm your consent",
        intro: "Agree to the terms to finish this step.",
        children: ConsentForm()
      });

    document.body.insertAdjacentHTML("afterbegin", App());

    const form = document.getElementById("consent-form");
    const checkbox = document.getElementById("consent");
    const field = checkbox.closest(".form-field");
    const error = document.getElementById("consent-error");
    const status = document.getElementById("form-status");

    const showError = () => {
      field.dataset.invalid = "true";
      checkbox.setAttribute("aria-invalid", "true");
      checkbox.setAttribute("aria-describedby", "consent-help consent-error");
      error.hidden = false;
    };

    const clearError = () => {
      field.dataset.invalid = "false";
      checkbox.removeAttribute("aria-invalid");
      checkbox.setAttribute("aria-describedby", "consent-help");
      error.hidden = true;
    };

    checkbox.addEventListener("change", () => {
      status.textContent = "";
      if (checkbox.checked) {
        clearError();
      }
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      status.textContent = "";

      if (!checkbox.checked) {
        showError();
        checkbox.focus();
        return;
      }

      clearError();
      status.textContent = "Consent submitted.";
    });
  </script>
</body>
</html>
